   * and returned to the caller. For any other non-redirect responses, the client will attempt a best-effort
   * retry by re-resolving the leader (same behavior as when an IOException/ChannelException occurs).
   *
   * If no terminalStatuses are provided, only HTTP 200 is considered terminal.
   */
  public <T, H extends FullResponseHolder<T>> H go(
      Request request,
      HttpResponseHandler<H, H> responseHandler,
      HttpResponseStatus... terminalStatuses
  ) throws IOException, InterruptedException
  {
    // Default terminal status is 200 if caller doesn't specify any
    final HttpResponseStatus[] allowed = (terminalStatuses == null || terminalStatuses.length == 0)
                                     ? new HttpResponseStatus[]{HttpResponseStatus.OK}
                                     : terminalStatuses;

    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    for (int counter = 0; counter < MAX_RETRIES; counter++) {

      final H fullResponseHolder;

      try {
        try {
          fullResponseHolder = httpClient.go(request, responseHandler).get();
        }
        catch (ExecutionException e) {
          // Unwrap IOExceptions and ChannelExceptions, re-throw others
          Throwables.propagateIfInstanceOf(e.getCause(), IOException.class);
          Throwables.propagateIfInstanceOf(e.getCause(), ChannelException.class);
