        log.warn("Request[%s] returned status [%s], retrying with refreshed leader discovery.", request.getUrl(), fullResponseHolder.getResponse().getStatus());
        try {
          if (request.getUrl().getQuery() == null) {
            request = withUrl(
                request,
                new URL(StringUtils.format("%s%s", getCurrentKnownLeader(false), request.getUrl().getPath()))
            );
