            RegexMatcherImpl::Word(WordMatcher::new(chir)?)
        } else {
            if chir.config().whole_line {
                chir = chir.into_whole_line();
            }
            RegexMatcherImpl::Standard(StandardMatcher::new(chir)?)
        })
    }

