 func (r *multipartRequest) TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions) (bool, error) {
+	// If there are parsed file parts for this key, set from them.
 	if files := r.MultipartForm.File[key]; len(files) != 0 {
 		return setByMultipartFormFile(value, field, files)
 	}

+	// Handle the case where the multipart form contains an empty value for a
+	// file field (e.g. filename="" was submitted). In that case the
+	// standard library may populate MultipartForm.Value with an empty string
+	// for the key while MultipartForm.File is empty. For optional file
+	// parameters we should treat this as "not set" (leave pointer nil)
+	// instead of attempting to unmarshal an empty string into a
+	// multipart.FileHeader which results in a JSON unmarshal error
+	// ("unexpected end of JSON input").
+	if r.MultipartForm != nil {
+		if vals, ok := r.MultipartForm.Value[key]; ok {
+			allEmpty := true
+			for _, v := range vals {
+				if v != "" {
+					allEmpty = false
+					break
+				}
+			}
+			if allEmpty {
+				// determine whether the destination field is a file header type
+				fhType := reflect.TypeOf(multipart.FileHeader{})
+				ft := field.Type
+				isFileField := false
+
+				switch ft.Kind() {
+				case reflect.Ptr:
+					if ft.Elem() == fhType {
+						isFileField = true
+					}
+				case reflect.Struct:
+					if ft == fhType {
+						isFileField = true
+					}
+				case reflect.Slice:
+					et := ft.Elem()
+					if et == fhType || (et.Kind() == reflect.Ptr && et.Elem() == fhType) {
+						isFileField = true
+					}
+				case reflect.Array:
+					et := ft.Elem()
+					if et == fhType || (et.Kind() == reflect.Ptr && et.Elem() == fhType) {
+						isFileField = true
+					}
+				}
+
+				if isFileField {
+					return false, nil
+				}
+			}
+		}
+	}
