+	// regexp to find existing percent-encodings that we should preserve
+	re := regexp.MustCompile(`%[0-9A-Fa-f]{2}`)
+
+	for i, part := range parts {
+		if part == "" {
+			continue
+		}
+
+		// Replace existing %XX sequences with temporary tokens so they won't
+		// be escaped by url.PathEscape, then restore them after escaping.
+		tokens := make([]string, 0)
+		mapping := make(map[string]string)
+		tmp := re.ReplaceAllStringFunc(part, func(m string) string {
+			tok := fmt.Sprintf("%%TOKEN%%%d%%", len(tokens))
+			tokens = append(tokens, tok)
+			mapping[tok] = m
+			return tok
