      }
      return t;
    });

    const expected = OrderedSet([
      Map({ id: 1, valid: true }),
      Map({ id: 2, valid: false }),
      Map({ id: 3, valid: true }),
    ]);

    expect(out).toEqual(expected);

    expect(out.has(first)).toBe(true);
    expect(out.has(second)).toBe(false);
    expect(out.has(third)).toBe(true);
  });
