            Some("never") => PagingMode::Never,
            Some("auto") | None => {
                // If we have -pp as an option when in auto mode, the pager should be disabled.
                let extra_plain = self.matches.occurrences_of("plain") > 1;
                if extra_plain || self.matches.is_present("no-paging") {
